export { ExpandOnHover } from "./components/expand-on-hover/ExpandOnHover";
export { useExpand } from "./hooks/useExpand";
export type {
  ExpandItem,
  ExpandVariant,
  ExpandAnimationType,
  ExpandOnHoverProps,
  ExpandOnHoverRef,
} from "./types";
export { Preview } from "./components/expand-on-hover/Preview";
export { CardContent } from "./components/expand-on-hover/CardContent";
export { ExpandCard } from "./components/expand-on-hover/ExpandCard";

import { ReactNode } from "react";

export interface ExpandItem {
  id: string;
  title: string;
  subtitle?: string;
  image: string;
  description?: string;
  year?: string;
  badge?: string;
  accent?: string; // e.g., custom hex, rgb, or styling class
}

export type ExpandVariant = "modern" | "minimal";
export type ExpandAnimationType = "spring" | "smooth";

export interface ExpandOnHoverProps {
  items: ExpandItem[];
  variant?: ExpandVariant;
  expandHeight?: number;
  collapsedHeight?: number;
  animation?: ExpandAnimationType;

  // Controlled & Uncontrolled states
  expandedId?: string | null;
  onExpandedChange?: (id: string | null) => void;
  defaultExpanded?: string | null;

  // Visuals and spacing
  gap?: number; // spacing in px
  borderRadius?: number; // border radius in px

  // Behaviors
  allowMultiple?: boolean; // if true, behaves like dynamic accordion
  hoverDelay?: number; // delay in ms before triggering expand
  clickToExpand?: boolean; // if true, ignore hovers and only expand on click/tap
  autoCollapseOnLeave?: boolean; // collapse all when cursor leaves component

  // Custom Render Prop
  renderItem?: (item: ExpandItem, isExpanded: boolean) => ReactNode;

  // Class overrides
  className?: string;
  cardClassName?: string;
}

export interface ExpandOnHoverRef {
  expand: (index: number) => void;
  collapse: () => void;
  next: () => void;
  prev: () => void;
}

import { useState, useRef, useCallback } from "react";
import { ExpandItem } from "../types";

interface UseExpandProps {
  items: ExpandItem[];
  expandedId?: string | null;
  onExpandedChange?: (id: string | null) => void;
  defaultExpanded?: string | null;
  hoverDelay?: number;
  clickToExpand?: boolean;
}

export function useExpand({
  expandedId: controlledId,
  onExpandedChange,
  defaultExpanded = null,
  hoverDelay = 50,
  clickToExpand = false,
}: UseExpandProps) {
  // Uncontrolled fallback state
  const [localExpandedId, setLocalExpandedId] = useState<string | null>(defaultExpanded);
  
  // Controlled vs Uncontrolled determination
  const isControlled = controlledId !== undefined;
  const activeId = isControlled ? controlledId : localExpandedId;

  const hoverTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const setExpanded = useCallback(
    (id: string | null) => {
      if (isControlled) {
        onExpandedChange?.(id);
      } else {
        setLocalExpandedId(id);
      }
    },
    [isControlled, onExpandedChange]
  );

  const clearHoverTimeout = useCallback(() => {
    if (hoverTimeoutRef.current) {
      clearTimeout(hoverTimeoutRef.current);
      hoverTimeoutRef.current = null;
    }
  }, []);

  const handleHoverStart = useCallback(
    (id: string) => {
      if (clickToExpand) return;
      clearHoverTimeout();
      
      if (hoverDelay > 0) {
        hoverTimeoutRef.current = setTimeout(() => {
          setExpanded(id);
        }, hoverDelay);
      } else {
        setExpanded(id);
      }
    },
    [clickToExpand, hoverDelay, setExpanded, clearHoverTimeout]
  );

  const handleHoverEnd = useCallback(() => {
    if (clickToExpand) return;
    clearHoverTimeout();
  }, [clickToExpand, clearHoverTimeout]);

  const handleCardClick = useCallback(
    (id: string) => {
      // Click/Tap toggle: if already expanded, collapse it; otherwise expand it.
      if (activeId === id) {
        setExpanded(null);
      } else {
        setExpanded(id);
      }
    },
    [activeId, setExpanded]
  );

  return {
    activeId,
    setExpanded,
    handleHoverStart,
    handleHoverEnd,
    handleCardClick,
    clearHoverTimeout,
  };
}

import React, { forwardRef, useImperativeHandle, useId, useRef } from "react";
import { LayoutGroup } from "framer-motion";
import { ExpandOnHoverProps, ExpandOnHoverRef } from "../../types";
import { useExpand } from "../../hooks/useExpand";
import { ExpandCard } from "./ExpandCard";
import { cn } from "@/lib/utils";

export const ExpandOnHover = forwardRef<ExpandOnHoverRef, ExpandOnHoverProps>(
  (
    {
      items,
      variant = "modern",
      expandHeight = 440,
      collapsedHeight = 64,
      animation = "spring",
      expandedId,
      onExpandedChange,
      defaultExpanded = null,
      gap = 12,
      borderRadius = 20,
      hoverDelay = 60,
      clickToExpand = false,
      autoCollapseOnLeave = true,
      renderItem,
      className,
      cardClassName,
    },
    ref
  ) => {
    // Unique LayoutGroup ID to prevent cross-component interference
    const layoutGroupId = useId();

    const {
      activeId,
      setExpanded,
      handleHoverStart,
      handleHoverEnd,
      handleCardClick,
    } = useExpand({
      items,
      expandedId,
      onExpandedChange,
      defaultExpanded,
      hoverDelay,
      clickToExpand,
    });

    const activeIndex = items.findIndex((item) => item.id === activeId);
    const resolvedActiveIndex = activeIndex === -1 ? null : activeIndex;

    useImperativeHandle(ref, () => ({
      expand: (index: number) => {
        if (index >= 0 && index < items.length) {
          setExpanded(items[index].id);
        }
      },
      collapse: () => {
        setExpanded(null);
      },
      next: () => {
        const nextIndex = activeIndex === -1 ? 0 : (activeIndex + 1) % items.length;
        setExpanded(items[nextIndex].id);
      },
      prev: () => {
        const prevIndex =
          activeIndex === -1
            ? items.length - 1
            : (activeIndex - 1 + items.length) % items.length;
        setExpanded(items[prevIndex].id);
      },
    }));

    // Keyboard navigation (Arrow keys + Escape + Space/Enter)
    const handleKeyDown = (e: React.KeyboardEvent, index: number) => {
      const targetItem = items[index];

      switch (e.key) {
        case "ArrowDown":
          e.preventDefault();
          const nextCard = document.getElementById(`card-${layoutGroupId}-${index + 1}`);
          nextCard?.focus();
          break;
        case "ArrowUp":
          e.preventDefault();
          const prevCard = document.getElementById(`card-${layoutGroupId}-${index - 1}`);
          prevCard?.focus();
          break;
        case "Escape":
          e.preventDefault();
          setExpanded(null);
          break;
        case "Enter":
        case " ":
          e.preventDefault();
          handleCardClick(targetItem.id);
          break;
        default:
          break;
      }
    };

    const leaveTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    // Smooth auto-collapse with 160ms buffer across card gaps
    const handleMouseLeaveContainer = () => {
      if (autoCollapseOnLeave && !clickToExpand) {
        if (leaveTimeoutRef.current) clearTimeout(leaveTimeoutRef.current);
        leaveTimeoutRef.current = setTimeout(() => {
          setExpanded(null);
        }, 160);
      }
    };

    const handleMouseEnterContainer = () => {
      if (leaveTimeoutRef.current) {
        clearTimeout(leaveTimeoutRef.current);
        leaveTimeoutRef.current = null;
      }
    };

    return (
      <LayoutGroup id={layoutGroupId}>
        <div
          onMouseEnter={handleMouseEnterContainer}
          onMouseLeave={handleMouseLeaveContainer}
          style={{ gap: `${gap}px` }}
          className={cn("flex flex-col w-full max-w-xl mx-auto", className)}
        >
          {items.map((item, index) => {
            const isExpanded = activeId === item.id;

            return (
              <ExpandCard
                key={item.id}
                id={`card-${layoutGroupId}-${index}`}
                item={item}
                index={index}
                activeIndex={resolvedActiveIndex}
                isExpanded={isExpanded}
                expandHeight={expandHeight}
                collapsedHeight={collapsedHeight}
                variant={variant}
                animation={animation}
                borderRadius={borderRadius}
                clickToExpand={clickToExpand}
                onHoverStart={() => handleHoverStart(item.id)}
                onHoverEnd={handleHoverEnd}
                onClick={() => handleCardClick(item.id)}
                onKeyDown={(e) => handleKeyDown(e, index)}
                renderItem={renderItem}
                cardClassName={cardClassName}
              />
            );
          })}
        </div>
      </LayoutGroup>
    );
  }
);

ExpandOnHover.displayName = "ExpandOnHover";

import { motion } from "framer-motion";
import { ExpandItem } from "../../types";

interface PreviewProps {
  item: ExpandItem;
  index: number;
  isExpanded?: boolean;
}

export function Preview({ item, index, isExpanded = false }: PreviewProps) {
  const formattedIndex = String(index + 1).padStart(2, "0");

  return (
    <div className="flex items-center justify-between w-full h-full px-6 select-none relative z-10">
      <div className="flex items-center gap-3.5 min-w-0">
        {/* Monospace index */}
        <span className="text-[11px] font-mono text-neutral-500 tabular-nums">
          {formattedIndex}
        </span>

        {/* Title */}
        <span className="text-sm font-semibold tracking-wide text-white/90 truncate">
          {item.title}
        </span>

        {/* Year or badge pill */}
        {(item.year || item.badge) && (
          <span className="text-[10px] font-mono tracking-wider text-neutral-400 bg-white/[0.06] border border-white/[0.08] px-2 py-0.5 rounded-full">
            {item.year || item.badge}
          </span>
        )}
      </div>

      {/* Right chevron indicator */}
      <motion.div
        animate={{ rotate: isExpanded ? 90 : 0 }}
        transition={{ duration: 0.25, ease: [0.25, 1, 0.5, 1] }}
        className="text-neutral-500 shrink-0 ml-2"
      >
        <svg
          className="w-4 h-4"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <polyline points="9 18 15 12 9 6" />
        </svg>
      </motion.div>
    </div>
  );
}

import { ExpandItem } from "../../types";

interface CardContentProps {
  item: ExpandItem;
  index: number;
  borderRadius?: number;
}

export function CardContent({ item }: CardContentProps) {
  return (
    <div className="relative w-full h-full flex flex-col justify-end p-6 sm:p-8 select-none z-10">
      <div className="space-y-3 max-w-xl">
        {/* Subtitle / Category / Badge */}
        {(item.subtitle || item.badge) && (
          <div className="flex items-center gap-2">
            <span className="text-[11px] font-mono uppercase tracking-[0.2em] text-white/60">
              {item.subtitle || item.badge}
            </span>
          </div>
        )}

        {/* Prominent Title */}
        <h3 className="text-2xl sm:text-3xl font-bold tracking-tight text-white drop-shadow-md">
          {item.title}
        </h3>

        {/* Description */}
        {item.description && (
          <p className="text-xs sm:text-sm text-neutral-300/90 leading-relaxed line-clamp-3 max-w-lg">
            {item.description}
          </p>
        )}

        {/* Year Pill & Status */}
        {item.year && (
          <div className="pt-1 flex items-center gap-2">
            <span className="text-[10px] font-mono text-neutral-400 bg-white/10 backdrop-blur-md border border-white/15 px-2.5 py-0.5 rounded-full">
              Release {item.year}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ExpandItem, ExpandVariant, ExpandAnimationType } from "../../types";
import { Preview } from "./Preview";
import { CardContent } from "./CardContent";
import { cn } from "@/lib/utils";

interface ExpandCardProps {
  id?: string;
  item: ExpandItem;
  index: number;
  activeIndex: number | null;
  isExpanded: boolean;
  expandHeight: number;
  collapsedHeight: number;
  variant: ExpandVariant;
  animation?: ExpandAnimationType;
  borderRadius: number;
  clickToExpand: boolean;
  onHoverStart: () => void;
  onHoverEnd: () => void;
  onClick: () => void;
  onKeyDown: (e: React.KeyboardEvent<HTMLDivElement>) => void;
  renderItem?: (item: ExpandItem, isExpanded: boolean) => React.ReactNode;
  cardClassName?: string;
}

export function ExpandCard({
  id,
  item,
  index,
  activeIndex,
  isExpanded,
  expandHeight,
  collapsedHeight,
  variant,
  animation = "spring",
  borderRadius,
  onHoverStart,
  onHoverEnd,
  onClick,
  onKeyDown,
  renderItem,
  cardClassName,
}: ExpandCardProps) {
  const cardRef = useRef<HTMLDivElement>(null);

  // Unified physics transitions
  const transitionConfig =
    animation === "smooth"
      ? {
          type: "tween" as const,
          ease: [0.25, 1, 0.5, 1], // easeOutQuart
          duration: 0.52,
        }
      : {
          type: "spring" as const,
          stiffness: 220,
          damping: 28,
          mass: 0.8,
        };

  let scale = 1;
  let opacity = 1;

  if (activeIndex !== null) {
    if (activeIndex === index) {
      scale = 1;
      opacity = 1;
    } else {
      scale = 0.99;
      opacity = 0.65;
    }
  }

  const isModern = variant === "modern";
  const variantClasses = isModern
    ? cn(
        "bg-neutral-900/70 border border-white/[0.08] backdrop-blur-md shadow-lg transition-colors duration-300 hover:border-white/20",
        isExpanded && "border-white/25 shadow-[0_20px_50px_-10px_rgba(0,0,0,0.85)]"
      )
    : "bg-neutral-950 border border-neutral-800 shadow-none";

  return (
    <motion.div
      ref={cardRef}
      role="button"
      tabIndex={0}
      aria-expanded={isExpanded}
      aria-controls={`panel-${item.id}`}
      id={id || `card-${index}`}
      layout
      transition={{
        layout: transitionConfig,
        scale: transitionConfig,
        opacity: transitionConfig,
      }}
      onMouseEnter={onHoverStart}
      onMouseLeave={onHoverEnd}
      onClick={onClick}
      onKeyDown={onKeyDown}
      animate={{
        scale,
        opacity,
      }}
      style={{
        height: isExpanded ? expandHeight : collapsedHeight,
        borderRadius: `${borderRadius}px`,
      }}
      className={cn(
        "relative w-full overflow-hidden cursor-pointer select-none outline-none group",
        "focus-visible:ring-2 focus-visible:ring-white/80 focus-visible:ring-offset-4 focus-visible:ring-offset-neutral-950",
        variantClasses,
        cardClassName
      )}
    >
      {/* Background Anime/Hero Poster Image (Always in DOM to eliminate paint stutter) */}
      <motion.div
        className="absolute inset-0 w-full h-full overflow-hidden pointer-events-none rounded-[inherit]"
        animate={{
          scale: isExpanded ? 1.04 : 1.0,
          opacity: isExpanded ? 0.85 : 0.16,
        }}
        transition={transitionConfig}
      >
        <img
          src={item.image}
          alt={item.title}
          loading="eager"
          className="w-full h-full object-cover rounded-[inherit] filter contrast-105"
        />
        {/* Soft Dark Vignette & Gradient Overlays */}
        <div
          className={cn(
            "absolute inset-0 transition-opacity duration-500 rounded-[inherit]",
            isExpanded
              ? "bg-gradient-to-t from-neutral-950 via-neutral-950/75 to-neutral-950/25"
              : "bg-neutral-950/70"
          )}
        />
      </motion.div>

      {/* Render Custom Item if provided */}
      {renderItem ? (
        renderItem(item, isExpanded)
      ) : (
        <>
          {/* Top Bar Preview (Always present at top of card) */}
          <div
            style={{ height: `${collapsedHeight}px` }}
            className="w-full flex items-center relative z-20"
          >
            <Preview item={item} index={index} isExpanded={isExpanded} />
          </div>

          {/* Expanded Content View (Smoothly fades in over the lower portion of the card) */}
          <AnimatePresence initial={false}>
            {isExpanded && (
              <motion.div
                key="content"
                initial={{ opacity: 0, y: 12 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{
                  opacity: 0,
                  y: 6,
                  transition: { duration: 0.14, ease: "easeOut" },
                }}
                transition={{
                  duration: 0.28,
                  ease: [0.25, 1, 0.5, 1],
                  delay: 0.08,
                }}
                className="absolute inset-0 w-full h-full pointer-events-none"
              >
                <CardContent item={item} index={index} borderRadius={borderRadius} />
              </motion.div>
            )}
          </AnimatePresence>
        </>
      )}
    </motion.div>
  );
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
